import {activityIds} from './economy.js';
import {validCharacter} from './journey.js';
let clientPromise;
export function getConfig(){try{return {...(window.AN_NHIEN_CONFIG||{}),...JSON.parse(localStorage.getItem('annhien-cloud')||'{}')}}catch{return window.AN_NHIEN_CONFIG||{}}}
export function configured(){const c=getConfig();return !!(c.supabaseUrl&&c.supabaseKey)}
export async function getClient(){if(!configured())return null;if(!clientPromise)clientPromise=(async()=>{const c=getConfig();const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.76.1');return createClient(c.supabaseUrl,c.supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}})})().catch(e=>{clientPromise=null;throw e});return clientPromise}
export function errorText(error){const msg=error?.message||String(error);if(/invalid login credentials/i.test(msg))return 'Email hoặc mật khẩu chưa đúng.';if(/email not confirmed/i.test(msg))return 'Hãy mở email xác nhận tài khoản trước khi đăng nhập.';if(/rate limit/i.test(msg))return 'Thao tác quá nhanh. Chờ một chút rồi thử lại.';if(/record_activity|schema cache|PGRST202/i.test(msg))return 'Máy chủ chưa cập nhật luật XP mới. Điểm đang chờ lưu; thử lại sau khi cập nhật Supabase.';if(/fetch|network/i.test(msg))return 'Không kết nối được Supabase. Kiểm tra mạng và cấu hình project.';return msg}
export async function rpc(name,args={}){const c=await getClient();if(!c)throw Error('Chưa cấu hình Supabase.');const {data,error}=await c.rpc(name,args);if(error)throw error;return data}
const guestKey='annhien-v2-guest';
export function localProfile(){try{const saved=JSON.parse(localStorage.getItem(guestKey));if(saved&&Number.isFinite(saved.xp))return saved}catch{}return {id:'guest',display_name:'Sen Nhỏ',xp:0,merit:0,role:'guest',daily:{},day:today(),claimed:false}}
export function saveLocal(profile){try{localStorage.setItem(guestKey,JSON.stringify(profile))}catch{throw Error('Trình duyệt chặn lưu dữ liệu. Tiến trình hiện chưa lưu được.')}}
export function today(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'})}
export async function loadPlayer(){const guest=sessionStorage.getItem('annhien-mode')==='guest';if(!guest&&configured()){const c=await getClient();const {data:{session},error}=await c.auth.getSession();if(error)throw error;if(!session)return null;const {data,error:pError}=await c.from('profiles').select('*').eq('id',session.user.id).single();if(pError)throw pError;return {...data,cloud:true,email:session.user.email,character:validCharacter(data.character)}}return {...localProfile(),cloud:false}}
export async function activityConfig(){const defaults=Object.fromEntries(activityIds.map(id=>[id,{xp:1,enabled:true}]));if(!configured()||sessionStorage.getItem('annhien-mode')==='guest')return defaults;const c=await getClient();const {data,error}=await c.from('activity_config').select('*');if(error)throw error;for(const r of data)defaults[r.id]=r;return defaults}
export class SharedRoom {
 constructor({profile,onPlayers,onBow,onStatus}){this.profile=profile;this.id=profile.cloud?profile.id:crypto.randomUUID();this.tabId=crypto.randomUUID();this.onPlayers=onPlayers;this.onBow=onBow;this.onStatus=onStatus;this.peers=new Map();this.lastSent=0;this.lastPos=null;this.disposed=false}
 async connect(){if(this.profile.cloud){this.client=await getClient();const {data:{session}}=await this.client.auth.getSession();await this.client.realtime.setAuth(session.access_token);if(this.disposed)return;this.channel=this.client.channel('temple:an-nhien',{config:{private:true,presence:{key:this.id},broadcast:{self:false}}});this.channel.on('presence',{event:'sync'},()=>{const online=new Set();for(const entries of Object.values(this.channel.presenceState()))for(const p of entries){if(p.id!==this.id){online.add(p.id);this.receive({...p,type:'position'})}}for(const id of this.peers.keys())if(!online.has(id))this.peers.delete(id);this.emit()}).on('broadcast',{event:'position'},({payload})=>this.receive({...payload,type:'position'})).on('broadcast',{event:'bow'},({payload})=>this.receive({...payload,type:'bow'})).subscribe(async status=>{if(status==='SUBSCRIBED'){this.onStatus('cloud');await this.channel.track(this.payload());this.send(true)}else if(['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(status))this.onStatus('error')});}else{this.local=new BroadcastChannel('annhien-local-room-v2');this.local.onmessage=({data})=>{if(data.type==='hello'){this.send(true);return}this.receive(data)};this.local.postMessage({type:'hello'});this.onStatus('local');this.heartbeat=setInterval(()=>{this.send(true);this.prune()},3000)}}
 payload(){return{id:this.id,tabId:this.tabId,name:this.profile.display_name,character:this.profile.character,merit:this.profile.merit,x:this.lastPos?.x||450,y:this.lastPos?.y||915,color:this.profile.cloud?'#8e9fe2':'#df9d73',map:this.lastPos?.map||'courtyard',animationStarted:this.lastPos?.animationStarted||0,action:this.lastPos?.action||'idle'}}
 receive(p){if(p.id===this.id||!p.id)return;if(p.type==='leave'){this.peers.delete(p.id);return this.emit()}if(p.type==='bow'){this.onBow(p);return}const x=Number(p.x),y=Number(p.y);if(!Number.isFinite(x)||!Number.isFinite(y)||x<80||x>870||y<610||y>1250)return;this.peers.set(p.id,{...p,name:String(p.name||'Bạn đồng hành').slice(0,24),x,y,last:Date.now()});this.emit()}
 emit(){this.onPlayers([...this.peers.values()])}
 prune(){const expiry=Date.now()-12000;for(const [id,p]of this.peers)if(p.last<expiry)this.peers.delete(id);this.emit()}
 send(force=false){if(this.disposed||(!force&&Date.now()-this.lastSent<300))return;this.lastSent=Date.now();const p=this.payload();if(this.channel)this.channel.send({type:'broadcast',event:'position',payload:p});else this.local?.postMessage({...p,type:'position'})}
 move(player){const mapChanged=this.lastPos?.map!==player.map;const changed=!this.lastPos||Math.hypot(player.x-this.lastPos.x,player.y-this.lastPos.y)>1||this.lastPos.action!==player.action||this.lastPos.map!==player.map||this.lastPos.animationStarted!==player.animationStarted;if(!changed)return;this.lastPos={x:player.x,y:player.y,action:player.action,map:player.map,animationStarted:player.animationStarted};if(mapChanged&&this.channel)this.channel.track(this.payload());this.send()}
 bow(target=null){const p={...this.payload(),target};if(this.channel)this.channel.send({type:'broadcast',event:'bow',payload:p});else this.local?.postMessage({...p,type:'bow'})}
 async close(){this.disposed=true;clearInterval(this.heartbeat);this.local?.postMessage({type:'leave',id:this.id});this.local?.close();if(this.channel)await this.client.removeChannel(this.channel)}
}

export async function saveCharacter(profile,character){const value=validCharacter(character);if(!value)throw Error('Hãy chọn giới tính và nghề hợp lệ.');if(profile.cloud){const r=await rpc('game_economy',{p_op:value.awakened?'awaken':'character',p_args:{gender:value.gender,career:value.career}});Object.assign(profile,r.profile);return;}saveLocal({...profile,character:value});profile.character=value;}
